const c=t=>{if(t instanceof Date)return Number.isNaN(t.getTime())?null:[t.getFullYear(),t.getMonth()+1,t.getDate()];const e=String(t),a=/^(\d{4})-(\d{2})-(\d{2})(?:$|T|\s)/.exec(e);if(a){const[,n,o,s]=a.map(Number),u=new Date(Date.UTC(n,o-1,s));return u.getUTCFullYear()!==n||u.getUTCMonth()+1!==o||u.getUTCDate()!==s?null:[n,o,s]}const r=new Date(e);return Number.isNaN(r.getTime())?null:[r.getFullYear(),r.getMonth()+1,r.getDate()]},i=t=>{if(!t)return"N/A";const e=c(t);if(!e)return String(t);const[a,r,n]=e;return`${String(n).padStart(2,"0")}/${String(r).padStart(2,"0")}/${a}`},m=t=>{if(!t)return"N/A";const e=c(t);if(!e)return String(t);const[a,r,n]=e;return new Date(Date.UTC(a,r-1,n)).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric",timeZone:"UTC"})},f=t=>{if(!t)return"";const e=c(t);if(!e)return"";const[a,r,n]=e;return`${a}-${String(r).padStart(2,"0")}-${String(n).padStart(2,"0")}`};export{f as a,i as b,m as f};
